import {money,outstandingAdvance,cents,visibleExecutionSummary} from './management-model.mjs';
export const managementPages=new Set(['ledger','settlements','assets','attendance','roles','competitors','dashboard']);
export function createManagementViews({api,h,heading,showPanel,source,localTime}){
 const $=s=>document.querySelector(s),blank=(title,desc)=>`<div class="empty"><h3>${h(title)}</h3><p>${h(desc)}</p></div>`;
 const head=title=>`<div class="dialog-header"><h2>${h(title)}</h2><button class="icon-button" data-manage-close aria-label="关闭管理详情">×</button></div>`;
 const facts=rows=>`<dl class="record-facts">${rows.map(([label,v])=>`<div><dt>${h(label)}</dt><dd>${h(v??'未填写')}</dd></div>`).join('')}</dl>`;
 const disabled=label=>`<button class="secondary" disabled title="当前仅查看云端记录">${h(label)}</button>`;
 let onOpen=null;
 document.addEventListener('click',e=>{const o=e.target.closest('[data-manage-open]'),c=e.target.closest('[data-manage-close]');if(o)onOpen?.(o.dataset.manageOpen);if(c)$('#cloud-detail').close();});
 function finance(data,page){
  const balance=outstandingAdvance(data),totalPaid=data.payments.reduce((n,p)=>n+cents(p.amountCents),0n).toString();
  $('#main').innerHTML=heading(page==='ledger'?'记账本':'结算与报销',page==='ledger'?'按发生日期核对支出，垫付与实际报销分别保留。':'跨月保留未结清垫付，结算与实际付款分开记录。')+`<section class="summary-strip"><div><b>${h(money(balance.total))}</b><span>累计未报销垫付</span></div><div><b>${h(money(totalPaid))}</b><span>累计实际报销</span></div></section><p class="finance-note">月份仅用于筛选记录，累计未报销余额不随月份重置。当前底层提供支出与垫付；收入记录另行补齐。</p><section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找明细<input id="finance-query" type="search" placeholder="用途、垫付人或店铺"></label><label>发生月份<input id="finance-month" type="month"></label><label>类型<select id="finance-mode"><option value="all">全部</option><option value="advance">个人垫付</option><option value="company">公司支付</option></select></label>${disabled(page==='ledger'?'＋ 记录支出':'新建结算')}</div><div id="finance-body"></div><div class="module-foot">本预览只读取现有记录，不发起结算、不确认付款，也不重新计入已结算支出。</div></section>`;
  if(page==='ledger'){
   onOpen=id=>{const r=data.records.find(r=>r.id===id);showPanel('支出详情',async()=>head(r.description)+facts([['发生日期',r.expenseDate],['金额',money(r.amountCents)],['支付方式',r.paymentMode==='advance'?'个人垫付':'公司支付'],['垫付人',r.payerName],['店铺',r.storeName],['分类',r.categoryName],['结算关联',r.settlementId?'已关联结算':'未关联结算']])+`<div class="detail-content"><h3>备注</h3><p class="preserve-text">${h(r.note||'暂无备注')}</p><h3>凭证 · ${(r.receipts||[]).length}</h3>${(r.receipts||[]).map(a=>`<p class="muted">${h(a.name)} · ${h(a.mime)}</p>`).join('')||'<p class="muted">暂无凭证附件</p>'}</div>`);};
   const render=()=>{const q=$('#finance-query').value.trim().toLowerCase(),month=$('#finance-month').value,mode=$('#finance-mode').value;const rows=data.records.filter(r=>(!month||r.expenseDate?.startsWith(month))&&(mode==='all'||r.paymentMode===mode)&&[r.description,r.payerName,r.storeName].join(' ').toLowerCase().includes(q));const sum=rows.reduce((n,r)=>n+cents(r.amountCents),0n).toString();$('#finance-body').innerHTML=`<p class="muted">${rows.length} 笔 · 本筛选支出发生额 ${h(money(sum))}</p><div class="table-scroll"><table class="record-table"><thead><tr><th>支出事项</th><th>发生日期</th><th>店铺 / 分类</th><th>支付方式</th><th>金额</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="table-title" data-manage-open="${h(r.id)}">${h(r.description)}</button></td><td>${h(r.expenseDate)}</td><td>${h(r.storeName||'未指定')}<p>${h(r.categoryName||'未分类')}</p></td><td>${h(r.paymentMode==='advance'?'垫付 · '+(r.payerName||'未提供姓名'):'公司支付')}</td><td class="money-cell">${h(money(r.amountCents))}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':blank('暂无符合条件的支出','调整月份或关键词后再查看。')}`;};$('#finance-query').oninput=render;$('#finance-month').onchange=render;$('#finance-mode').onchange=render;render();
  }else{
   $('#finance-month').closest('label').hidden=true;$('#finance-mode').closest('label').hidden=true;
   onOpen=id=>{const s=data.settlements.find(s=>s.id===id);showPanel('结算详情',async()=>head('垫付结算 · '+s.payerName)+facts([['垫付人',s.payerName],['结算金额',money(s.totalCents)],['实际已报销',money(s.paidCents)],['尚未结清',money(s.remainingCents)],['原支出区间',(s.startDate||'不限')+' — '+(s.endDate||'不限')]])+`<div class="detail-content"><h3>支出明细</h3>${s.items.map(i=>{const r=data.records.find(r=>r.id===i.expenseId);return `<p class="preserve-text">${h(r?.description||'原记录暂不可用')} · ${h(money(i.amountCents))}</p>`;}).join('')}<h3>实际付款记录</h3>${data.payments.filter(p=>p.settlementId===s.id).map(p=>`<article class="observation"><b>${h(money(p.amountCents))}</b><p>${h(p.paidDate)} · ${h(p.note||'无备注')}</p></article>`).join('')||'<p class="muted">还没有实际付款记录。</p>'}</div>`);};
   const render=()=>{const q=$('#finance-query').value.trim().toLowerCase();const pending=data.records.filter(r=>r.paymentMode==='advance'&&!r.settlementId&&[r.description,r.payerName,r.storeName].join(' ').toLowerCase().includes(q));const rows=data.settlements.filter(s=>[s.payerName,s.note].join(' ').toLowerCase().includes(q));$('#finance-body').innerHTML=`<h2 class="section-title">未纳入结算的垫付 · ${pending.length} 笔</h2>${pending.map(r=>`<article class="balance-row"><span><b>${h(r.description)}</b><small>${h(r.expenseDate)} · ${h(r.payerName||'未提供姓名')}</small></span><b>${h(money(r.amountCents))}</b></article>`).join('')||'<p class="muted">当前没有未纳入结算的垫付。</p>'}<h2 class="section-title">已有结算 · ${rows.length} 单</h2>${rows.map(s=>`<button class="balance-row" data-manage-open="${h(s.id)}"><span><b>${h(s.payerName)}</b><small>明细 ${s.items.length} 笔 · ${h(cents(s.remainingCents)>0n?'未结清':'已结清')}</small></span><span><b>${h(money(s.remainingCents))}</b><small>尚未结清 · 总额 ${h(money(s.totalCents))}</small></span><span class="task-arrow">›</span></button>`).join('')||'<p class="muted">当前没有结算记录。</p>'}`;};$('#finance-query').oninput=render;render();
  }
 }
 async function paged(page,signal,user){
  const assets=page==='assets';
  $('#main').innerHTML=heading(assets?'工作室财产管理':'考勤记录',assets?'先集中查看已有拍摄样品，设备档案后续补齐。':'查看原始出勤与更正时间，不自动推算工资或考勤奖罚。')+`<section class="work-panel module-panel"><div class="module-toolbar">${assets?'<label class="module-search">查找样品<input id="manage-query" type="search" placeholder="样品、产品或存放位置"></label>':'<label>开始日期<input id="attendance-from" type="date"></label><label>结束日期<input id="attendance-to" type="date"></label>'}<span class="muted">${assets?'拍摄样品 · 设备待接入':user.role==='admin'?'团队记录':'本人记录'}</span></div><div id="manage-paged-list"></div><div class="pager"><button id="manage-prev" class="secondary">上一页</button><span id="manage-paged-caption"></span><button id="manage-next" class="secondary">下一页</button></div></section>`;
  let offset=0,request,serial=0,timer,rows=[];
  onOpen=id=>{const r=rows.find(r=>r.id===id);showPanel(assets?'样品资料':'考勤记录',async()=>head(assets?r.name:r.memberName||'考勤记录')+(assets?facts([['产品',r.productName],['存放位置',r.warehouse_location],['保管人',r.keeperName],['可用件数',r.available_quantity],['尚未归还件数',r.outstandingQuantity??'未提供'],['状态',r.active?'启用':'停用']]):facts([['日期',r.work_date],['类型',r.kind==='field'?'外勤':'工作室'],['审核状态',({pending:'待审核',approved:'已批准',rejected:'已驳回','not-required':'无需审核'})[r.approval_status]||r.approval_status],['原始签到',localTime(r.original_in)],['原始签退',localTime(r.original_out)],['更正签到',localTime(r.adjusted_in)],['更正签退',localTime(r.adjusted_out)]]))+`<p class="preserve-text">${h(r.note||r.reason||'暂无补充说明')}</p>`);};
  const load=async()=>{request?.abort();request=new AbortController();const key=++serial,combined=AbortSignal.any([signal,request.signal]);try{const data=assets?await api.samples({offset,q:$('#manage-query').value},combined):await api.attendance({offset,view:user.role==='admin'?'team':'own',from:$('#attendance-from').value,to:$('#attendance-to').value},combined);if(combined.aborted||key!==serial)return;rows=data.rows;offset=data.offset;$('#manage-paged-list').innerHTML=rows.map(r=>assets?`<button class="asset-row" data-manage-open="${h(r.id)}"><span class="account-symbol">样</span><span><b>${h(r.name)}</b><small>${h(r.productName||'未指定产品')} · ${h(r.warehouse_location||'位置未填写')}</small></span><span><b>${h(r.available_quantity)}</b><small>可用件数</small></span><span class="task-arrow">›</span></button>`:`<button class="asset-row" data-manage-open="${h(r.id)}"><span><b>${h(r.memberName||'成员未提供')}</b><small>${h(r.work_date)} · ${h(r.kind==='field'?'外勤':'工作室')}</small></span><span><b>${h(localTime(r.adjusted_in||r.original_in))}</b><small>签到${r.adjusted_in?' · 已更正':''}</small></span><span><b>${h(localTime(r.adjusted_out||r.original_out))}</b><small>签退${r.adjusted_out?' · 已更正':''}</small></span><span class="task-arrow">›</span></button>`).join('')||blank(assets?'暂无符合条件的样品':'暂无符合条件的考勤记录','记录为空时不使用示例数据填充。');$('#manage-paged-caption').textContent=`${offset+1} — ${offset+rows.length} / ${data.total} 条`;if(!data.total)$('#manage-paged-caption').textContent='0 条记录';$('#manage-prev').disabled=offset===0;$('#manage-next').disabled=offset+data.limit>=data.total;}catch(e){if(e.name==='AbortError'||signal.aborted)return;$('#manage-paged-list').innerHTML=blank('资料暂时无法读取',e.message);}};
  $('#manage-prev').onclick=()=>{offset=Math.max(0,offset-50);load();};$('#manage-next').onclick=()=>{offset+=50;load();};if(assets)$('#manage-query').oninput=()=>{offset=0;clearTimeout(timer);timer=setTimeout(()=>{if(!signal.aborted)load();},250);};else for(const id of ['attendance-from','attendance-to'])$('#'+id).onchange=()=>{offset=0;load();};signal.addEventListener('abort',()=>{request?.abort();clearTimeout(timer);},{once:true});await load();
 }
 function roles(rows){$('#main').innerHTML=heading('用户与角色权限','查看系统登录身份，和业务成员、运营账号分开管理。')+`<section class="work-panel module-panel"><div class="module-toolbar"><span class="muted">${rows.length} 个已登记登录用户</span>${disabled('管理登录身份')}</div><table class="record-table"><thead><tr><th>登录用户名</th><th>角色</th><th>账号状态</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${h(r.username)}</td><td>${r.role==='admin'?'管理员':'员工'}</td><td>${r.active?'启用':'停用'}</td></tr>`).join('')}</tbody></table><div class="planning-rule">角色和对象范围由原服务端验证。这里不显示密码、密钥或会话凭证，也不通过前端切换角色。</div></section>`;}
 function competitors(rows){
  $('#main').innerHTML=heading('竞品观测','保留人工观察与历史快照，给内容和产品测试提供参考。')+`<section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找竞品<input id="competitor-search" type="search" placeholder="名称、小红书号或观察备注"></label>${disabled('＋ 记录竞品')}</div><div id="competitor-list"></div><div class="module-foot">记录时间和价格/销量快照按原数据展示，不代表实时数据或自动采集。</div></section>`;
  onOpen=id=>{const c=rows.find(r=>r.id===id);showPanel('竞品资料',async()=>head(c.name)+facts([['小红书号',c.xhsId],['状态',c.status]])+source(c.profileUrl)+`<div class="detail-content"><h3>观察说明</h3><p class="preserve-text">${h(c.notes||'暂无说明')}</p><h3>竞品商品 · ${(c.products||[]).length}</h3>${(c.products||[]).map(p=>`<article class="observation"><b>${h(p.name)}</b><p>记录价格：${h(p.price??'未记录')}</p>${source(p.productUrl)}${(p.snapshots||[]).map(s=>`<p class="muted">${h(s.snapshotDate)} · 记录销量 ${h(s.sales??'未记录')} · 价格 ${h(s.price??'未记录')}</p>`).join('')}</article>`).join('')||'<p class="muted">暂无竞品商品。</p>'}<h3>观察记录</h3>${(c.observations||[]).map(o=>`<article class="observation"><small>${h(o.observationDate)}</small><p class="preserve-text">${h(o.content)}</p></article>`).join('')||'<p class="muted">暂无观察内容。</p>'}</div>`);};
  const render=()=>{const q=$('#competitor-search').value.trim().toLowerCase();const list=rows.filter(c=>[c.name,c.xhsId,c.notes].join(' ').toLowerCase().includes(q));$('#competitor-list').innerHTML=list.map(c=>`<button class="account-row" data-manage-open="${h(c.id)}"><span class="account-symbol">竞</span><span><b>${h(c.name)}</b><small>${h(c.xhsId||'未填写账号标识')} · ${(c.products||[]).length} 个记录商品</small></span><span class="type-tag">${h(c.status)}</span><span class="task-arrow">›</span></button>`).join('')||blank('暂无符合条件的竞品','后续记录会保留在同一份观测档案中。');};$('#competitor-search').oninput=render;render();
 }
 function dashboard(rows,user){
  const summary=visibleExecutionSummary(rows),value=v=>v===null?'未提供':v;
  const pubs=rows.filter(t=>t.kind==='publication');
  $('#main').innerHTML=heading('数据驾驶舱','先看执行与回填事实，再进入原始记录判断原因。')+`<section class="summary-strip"><div><b>${summary.taskCount}</b><span>可见发布事项</span></div><div><b>${h(value(summary.published))}</b><span>累计已发布</span></div><div><b>${h(value(summary.filled))}</b><span>已有观察数据的发布</span></div></section><section class="work-panel module-panel"><div class="panel-head"><h2>执行事项概览</h2></div>${pubs.map(t=>`<button class="balance-row" data-live-task="${h(t.id)}"><span><b>${h(t.title)}</b><small>${h(t.accountName||'账号未提供')} · ${h(t.assignee||'负责人未提供')}</small></span><span><b>${h(t.publishedCount??'未提供')} / ${h(t.targetCount??'未提供')}</b><small>发布 / 计划</small></span></button>`).join('')||blank('暂无可见的发布执行事项','不会将空值或未采集数据填成销量。')}<div class="planning-rule">范围：${user.role==='admin'?'当前管理员可读取的事项':'当前账号本人可读取的事项'}，累计至本次读取；不是按自然月汇总，也不代表平台全部账号数据。回填数表示有观察记录的发布篇数，不是观察次数。</div><p class="muted">账号效果、商品效果与爆款洞察需要明确观察窗口、数据口径及阈值后继续扩展。</p></section>`;
 }
 return {async render(page,signal,user){onOpen=null;
  if(page==='ledger'||page==='settlements'){const d=await api.finance(signal);if(!signal.aborted)finance(d,page);}
  if(page==='assets'||page==='attendance')await paged(page,signal,user);
  if(page==='roles'){const rows=await api.loginAccounts(signal);if(!signal.aborted)roles(rows);}
  if(page==='competitors'){const rows=await api.competitors(signal);if(!signal.aborted)competitors(rows);}
  if(page==='dashboard'){const rows=await api.workTasks(signal);if(!signal.aborted)dashboard(rows,user);}
 }};
}
